def generate(seed):
    r = random.Random(seed)
    for _ in range(600):
        A = r.sample("ABCDEFGHJKLMNPRSTUVW", 6)
        pat = [1] * r.randint(2, 3)                       # left end anchored: no shelf-end ambiguity
        while len(pat) < 52:
            pat += [0] * (1 if r.random() < 0.70 else 2)  # holes: one slot, or two (decoy)
            pat += [1] * r.choice((1, 1, 2, 2, 3))        # runs of books; singletons are decoys
        pat += [0] * (1 if r.random() < 0.70 else 2)
        pat += [1] * r.randint(2, 3)                      # right end anchored
        W = len(pat)
        if not (55 <= W <= 62):
            continue
        g = lambda j: 0 <= j < W and not pat[j]
        cand, iso, far = [], [], []
        for i in range(W):
            if not pat[i]:
                continue
            d = g(i + 1) - g(i - 1)
            if not d:
                if g(i + 1) and g(i - 1):
                    iso.append(i)                         # holes both sides: nothing pushes it over
            elif 0 <= i + 2 * d < W and pat[i + 2 * d]:
                cand.append((i, d))                       # something to lean on may be there
            else:
                far.append(i)                             # two-slot hole: nothing within reach
        if not (16 <= len(cand) <= 24) or len(iso) < 4 or len(far) < 4:
            continue
        # Deal the interesting slots so that the four named letters own most of the
        # candidates AND at least one decoy of each kind: a near-miss rule then changes
        # a named tally in (almost) every instance.
        lab = [None] * W
        cyc = A[:4] + A[:4] + A[4:]
        r.shuffle(cyc)
        idx = list(range(len(cand)))
        r.shuffle(idx)
        for k, ci in enumerate(idx):
            lab[cand[ci][0]] = cyc[k % len(cyc)]
        for pool in (iso, far):
            q = A[:4] + A[4:]
            r.shuffle(q)
            p = list(pool)
            r.shuffle(p)
            for k, i in enumerate(p):
                lab[i] = q[k % 6]
        L = "".join(lab[j] or (r.choice(A) if pat[j] else ".") for j in range(W))
        named = A[:4]
        hmax = r.choice((5, 6, 7, 8, 9))
        H = [r.randint(1, hmax) if pat[j] else 0 for j in range(W)]
        cnt = {}
        for i, d in cand:
            if H[i + 2 * d] > H[i]:
                cnt[L[i]] = cnt.get(L[i], 0) + 1
        tal = [cnt.get(ch, 0) for ch in named]
        if sum(1 for v in tal if v) < 3 or sum(tal) < 5 or max(tal) > 9:
            continue
        r.shuffle(named)
        return L + "/" + "".join(ch + str(cnt.get(ch, 0)) for ch in named)
    return ("MMB.RB.M.RRB.BM.J.MRR.BBM.J.RM.J.BR.MMB.J.RRM.BB.MR.JJM/M2B1R2J1")

