def tally(L, W, H):
    T = {}
    for i in range(W):
        if H[i]:
            d = (0 <= i + 1 < W and not H[i + 1]) - (0 <= i - 1 < W and not H[i - 1])
            if d and 0 <= i + 2 * d < W and H[i + 2 * d] > H[i]:
                T[L[i]] = T.get(L[i], 0) + 1
    return T


def cost(L, W, H, tgt):
    T = tally(L, W, H)
    return sum(abs(T.get(ch, 0) - v) for ch, v in tgt.items())


def solve(clue):
    L, K = clue.split("/")
    W = len(L)
    tgt = {K[k]: int(K[k + 1]) for k in range(0, len(K), 2)}
    r = random.Random(clue)
    books = [j for j in range(W) if L[j] != "."]
    for _ in range(30):
        hmax = r.choice((5, 6, 7, 8, 9))
        H = [r.randint(1, hmax) if L[j] != "." else 0 for j in range(W)]
        e = cost(L, W, H, tgt)
        for _ in range(500):
            if not e:
                break
            j = r.choice(books)
            old = H[j]
            H[j] = r.randint(1, hmax)
            e2 = cost(L, W, H, tgt)
            if e2 <= e:
                e = e2
            else:
                H[j] = old
        if not e:
            M = max(H)
            rows = ["".join(L[j] if H[j] >= M - t else "." for j in range(W)) for t in range(M)]
            return "\n".join(rows + ["=" * W])
    return ""

